const fetch = require('node-fetch');
const fs = require('fs');
const path = require('path');

const API_URL = 'https://staging.crossmint.com/api/2022-06-09/collections/default/nfts';
const API_KEY = process.env.CROSSMINT_API_KEY;
const OUTPUT_FILE = '/home/user/mint_response.json';

async function mintNFT() {
  try {
    if (!API_KEY) {
      throw new Error('CROSSMINT_API_KEY environment variable is not set');
    }

    const requestBody = {
      recipient: 'email:test@example.com:polygon-amoy',
      metadata: {
        name: 'Welcome NFT',
        description: 'A welcome gift',
        image: 'https://example.com/nft.png'
      }
    };

    const response = await fetch(API_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': API_KEY
      },
      body: JSON.stringify(requestBody)
    });

    const responseData = await response.json();

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    // Write successful response to file
    fs.writeFileSync(OUTPUT_FILE, JSON.stringify(responseData, null, 2));
    console.log('NFT minted successfully. Response written to', OUTPUT_FILE);

  } catch (error) {
    // Handle errors gracefully - write error to file
    const errorResponse = {
      error: error.message
    };
    fs.writeFileSync(OUTPUT_FILE, JSON.stringify(errorResponse, null, 2));
    console.error('Error minting NFT:', error.message);
    console.error('Error details written to', OUTPUT_FILE);
  }
}

mintNFT();

